```gdscript
# host ui_scale() 同公式：maxf(1, 视口宽/2400) × 1.35（不写死分辨率）
func _us() -> float:
	var vp := get_viewport()
	if vp == null:
		return UI_SCALE_EXTRA
	return maxf(1.0, vp.get_visible_rect().size.x / BASE_W) * UI_SCALE_EXTRA

func _fs(base: float) -> float:
	return float(int(round(base * _us())))

func _text(pos: Vector2, txt: String, sz: float, col: Color) -> void:
	var isz := int(round(sz))
	draw_string(_f, pos + Vector2(1.5, 1.5), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, isz, Color(0, 0, 0, 0.55))
	draw_string(_f, pos, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, isz, col)

func _tw(txt: String, sz: float) -> float:
	return _f.get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, int(round(sz))).x

func _th(sz: float) -> float:
	return _f.get_height(int(round(sz)))

func _asc(sz: float) -> float:
	return _f.get_ascent(int(round(sz)))

# 纵向居中堆叠若干行文字（host VBoxContainer 布局等价）
func _vstack(x: float, center_y: float, txts: Array, szs: Array, cols: Array, sep: float) -> void:
	var total := 0.0
	for i in range(txts.size()):
		total += _th(szs[i])
		if i > 0:
			total += sep
	var y := center_y - total * 0.5
	for i in range(txts.size()):
		_text(Vector2(x, y + _asc(szs[i])), str(txts[i]), float(szs[i]), cols[i])
		y += _th(szs[i]) + sep
```

`_fs` returns float; passing float sz to functions with float ok.

_panel_rect etc:
```gdscript
func _panel_rect() -> Rect2:
	var vp := get_viewport()
	var area := (vp.get_visible_rect().size if vp != null else size)
	# host：水平居中 2160 宽、垂直满高
	return Rect2(Vector2((area.x - PANEL_W) * 0.5, 0.0), Vector2(PANEL_W, area.y))

func _close_rect(p: Rect2) -> Rect2:
	return Rect2(Vector2(p.end.x - 56.0, p.position.y + 6.0), Vector2(CLOSE_W, CLOSE_W))

func _attr_w() -> float:
	var s := _us()
	return ATTR_PAD * 2.0 * s + ATTR_COL_W * 2.0 * s + ATTR_GAP * s

func _attr_h() -> float:
	var s := _us()
	return ATTR_PAD * 2.0 * s + ATTR_LEGEND_H * s + ATTR_ROW_H * s * float(ATTR_ROWS_PER_COL)

# host 卡片高度公式（panel_h=1000、统计头 55、卡间距 4）→ 再按可用高度上限收紧，避免溢出
func _metrics(n: int, avail: float) -> Dictionary:
	if n <= 0:
		return {"h": CARD_MIN_H, "main": 12.0, "sub": 11.0}
	var h := maxf(CARD_MIN_H, (1000.0 - TEAM_HDR_H - CARD_GAP * float(n)) / float(n))
	var cap := (avail - CARD_GAP * float(n)) / float(n)
	h = maxf(CARD_MIN_H, minf(h, cap))
	var fm := float(maxi(12, int(h / 4.2)))
	return {"h": h, "main": fm, "sub": maxf(11.0, fm - 2.0)}

func _sorted() -> Array:
	var out := rows.duplicate()
	out.sort_custom(func(a, b): return int(a[9]) > int(b[9]))
	return out

func _team_sum(list: Array, team: int) -> Array:
	var gold := 0
	var kills := 0
	for e in list:
		if int(e[2]) == team:
			gold += int(e[9])
			kills += int(e[6])
	return [gold, kills]

func _gold_txt(v: int) -> String:
	return "%.1fk" % (float(v) / 1000.0) if v >= 1000 else str(v)
```
Careful with ternary precedence: `return "%.1fk" % (float(v) / 1000.0) if v >= 1000 else str(v)` — GDScript parses ternary correctly? `a % b if cond else c` → ternary applies to whole expression? In GDScript, ternary `x if cond else y` where x is "%.1fk" % (...) — I think it parses as expected, but to be safe use explicit:
```gdscript
func _gold_txt(v: int) -> String:
	if v >= 1000:
		return "%.1fk" % (float(v) / 1000.0)
	return str(v)
```

