func _draw() -> void:
	var vp := get_viewport()
	if vp == null:
		return
	var area := vp.get_visible_rect().size
	var p := _panel_rect()
	# 全屏遮罩（host hero_detail_dim 0.4）+ 黑底面板（host _apply_panel_style 0.88）
	draw_rect(Rect2(Vector2.ZERO, area), C_DIM)
	draw_rect(p, C_PANEL_BG)
	# 标题区：host hd_title(44,16) 28 金 / hd_sub(48,58) 13 灰 / 金线(44,82) 360×3
	var t_sz := _fs(28)
	_text(Vector2(p.position.x + 44.0, p.position.y + 16.0 + _asc(t_sz)), "战场信息", t_sz, Color.GOLD)
	var s_sz := _fs(13)
	var sub := "按总经济排序 · 点击空白处关闭"
	if view == "attr":
		sub = "按总经济排序 · 下方为本机英雄属性 · 点击空白处关闭"
	_text(Vector2(p.position.x + 48.0, p.position.y + 58.0 + _asc(s_sz)), sub, s_sz, C_SUB)
	draw_rect(Rect2(p.position + Vector2(44.0, 82.0), Vector2(360.0, 3.0)), C_GOLD_LINE)
	# 右上关闭 ×（host close_btn：-56..-6 / 6..56，字号 26）
	var cb := _close_rect(p)
	var csb := StyleBoxFlat.new()
	csb.bg_color = Color(0.22, 0.23, 0.26, 0.95)
	csb.set_corner_radius_all(5)
	csb.set_border_width_all(1)
	csb.border_color = Color(1, 1, 1, 0.25)
	draw_style_box(csb, cb)
	var x_sz := _fs(26)
	var xw := _tw("×", x_sz)
	_text(Vector2(cb.position.x + (CLOSE_W - xw) * 0.5, cb.position.y + (CLOSE_W - _th(x_sz)) * 0.5 + _asc(x_sz)),
			"×", x_sz, Color(1, 1, 1, 0.9))
	# 名单：团队统计头 + 按总经济排序的单列英雄卡
	var list := _sorted()
	var attr_h := (_attr_h() + 16.0) if view == "attr" else 0.0
	var avail := p.size.y - CONTENT_TOP - TEAM_HDR_H - 20.0 - attr_h - 16.0
	var met := _metrics(list.size(), avail)
	var card_h: float = float(met["h"])
	var fm: float = float(met["main"])
	var fs_: float = float(met["sub"])
	var y_hdr := p.position.y + CONTENT_TOP
	_draw_team_header(p, y_hdr, list, _fs(fm + 2.0), _fs(fm), _fs(fm + 4.0))
	draw_rect(Rect2(p.position.x + 8.0, y_hdr + TEAM_HDR_H + 6.0, PANEL_W - 16.0, 1.0), Color(1, 1, 1, 0.12))
	var self_nid := int(own.get("nid", -1))
	var y_card := y_hdr + TEAM_HDR_H + 16.0
	for i in range(list.size()):
		_draw_card(Rect2(Vector2(p.position.x, y_card), Vector2(PANEL_W, card_h)), list[i], self_nid, _fs(fm), _fs(fs_))
		y_card += card_h + CARD_GAP
	if view == "attr":
		_draw_attr_table(Vector2(p.position.x + 30.0, y_card + 16.0), self_nid)
