func _text(pos: Vector2, txt: String, sz: float, col: Color) -> void:
	var isz := int(round(sz))
	draw_string(_f, pos + Vector2(1.5, 1.5), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, isz, Color(0, 0, 0, 0.55))
	draw_string(_f, pos, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, isz, col)

func _tw(txt: String, sz: float) -> float:
