func _th(sz: float) -> float:
	return _f.get_height(int(round(sz)))

func _asc(sz: float) -> float:
	return _f.get_ascent(int(round(sz)))

# 纵向居中堆叠若干行文字（host VBoxContainer 布局等价）
func _vstack(x: float, center_y: float, txts: Array, szs: Array, cols: Array, sep: float) -> void:
	var total := 0.0
	for i in range(txts.size()):
		total += _th(szs[i])
		if i > 0:
			total += sep
	var y := center_y - total * 0.5
	for i in range(txts.size()):
		_text(Vector2(x, y + _asc(szs[i])), str(txts[i]), float(szs[i]), cols[i])
		y += _th(szs[i]) + sep
