func _panel_rect() -> Rect2:
	var vp := get_viewport()
	var area := (vp.get_visible_rect().size if vp != null else size)
	# host：水平居中 2160 宽、垂直满高
	return Rect2(Vector2((area.x - PANEL_W) * 0.5, 0.0), Vector2(PANEL_W, area.y))

func _close_rect(p: Rect2) -> Rect2:
	return Rect2(Vector2(p.end.x - 56.0, p.position.y + 6.0), Vector2(CLOSE_W, CLOSE_W))

func _attr_w() -> float:
	var s := _us()
	return ATTR_PAD * 2.0 * s + ATTR_COL_W * 2.0 * s + ATTR_GAP * s

func _attr_h() -> float:
	var s := _us()
	return ATTR_PAD * 2.0 * s + ATTR_LEGEND_H * s + ATTR_ROW_H * s * float(ATTR_ROWS_PER_COL)

# host 卡片高度公式（panel_h=1000、统计头 55、卡间距 4）→ 再按可用高度上限收紧，避免溢出
func _metrics(n: int, avail: float) -> Dictionary:
	if n <= 0:
		return {"h": CARD_MIN_H, "main": 12.0, "sub": 11.0}
	var h := maxf(CARD_MIN_H, (1000.0 - TEAM_HDR_H - CARD_GAP * float(n)) / float(n))
	var cap := (avail - CARD_GAP * float(n)) / float(n)
	h = maxf(CARD_MIN_H, minf(h, cap))
	var fm := float(maxi(12, int(h / 4.2)))
	return {"h": h, "main": fm, "sub": maxf(11.0, fm - 2.0)}

func _sorted() -> Array:
	var out := rows.duplicate()
	out.sort_custom(func(a, b): return int(a[9]) > int(b[9]))
	return out

func _team_sum(list: Array, team: int) -> Array:
	var gold := 0
	var kills := 0
	for e in list:
		if int(e[2]) == team:
			gold += int(e[9])
			kills += int(e[6])
	return [gold, kills]

func _gold_txt(v: int) -> String:
	return "%.1fk" % (float(v) / 1000.0) if v >= 1000 else str(v)
