		["chev", Color(0.45, 0.9, 0.7), "%.0f" % float(e[15])],
	]
	var skills := _skill_texts(is_own)
	var icon := 20.0
	var r1 := maxf(icon, _th(fs_))
	var has_sk := skills.size() > 0
	var r2 := _th(fs_) if has_sk else 0.0
