func _draw_card(card: Rect2, e: Array, self_nid: int, fm: float, fs_: float) -> void:
	var is_ally := int(e[2]) == 0
	var is_own := int(e[0]) == self_nid
	# 卡片底色/描边（host StyleBoxFlat：我方蓝底青边 / 敌方红底红边），自己额外加金边
	draw_style_box(_sb_ally if is_ally else _sb_enemy, card)
	if is_own:
		draw_style_box(_sb_own, card)
	var cy := card.position.y + card.size.y * 0.5
	var x := card.position.x + 10.0   # border_left 4 + content_margin 6
	# 1) 头像盘（host HeroDisc 60 宽：阵营外环 + 血量状态弧）
	var maxhp := maxf(1.0, float(e[5]))
	var ratio := clampf(float(e[4]) / maxhp, 0.0, 1.0)
	_draw_disc(Rect2(Vector2(x, card.position.y + 2.0), Vector2(DISC_W, card.size.y - 4.0)), is_ally, ratio)
	x += DISC_W + 8.0
	# 2) 状态 / 名字 / 等级（host left_box 180 宽：font_main、font_main、font_sub，1px 行距）
	var nm := str(e[1])
	var name_col := Color.WHITE if is_ally else Color(1.0, 0.55, 0.55)
	if is_own:
		nm = ">> " + nm
		name_col = Color(1.0, 0.88, 0.4)
	_vstack(x, cy, ["存活", nm, "Lv.%d" % int(e[3])], [fm, fm, fs_],
			[Color(0.3, 1.0, 0.4), name_col, Color.GOLD], 1.0)
	# 3) 中间（属性圆徽章 + 技能行）、4) 右侧（KDA/总经济/装备）；右列按装备行宽撑开（host 每件 min 80）
	var right_w := maxf(RIGHT_W, _equip_w(e))
	var mid_x := x + LEFT_W + 8.0
	var mid_r := card.end.x - 7.0 - right_w - 8.0
	_draw_mid(mid_x, mid_r, cy, e, is_own, fs_)
	var rx := card.end.x - 7.0 - right_w
	_draw_right(Rect2(Vector2(rx, card.position.y + 2.0), Vector2(right_w, card.size.y - 4.0)), e, cy, fs_)

func _equip_w(e: Array) -> float:
	var ek: Array = e[10]
	var n := mini(ek.size(), 6)
	if n <= 0:
		return 0.0
	return float(n) * (80.0 + 3.0) - 3.0

# host HeroDisc：暗内盘 + 阵营色外环 + 血量弧(绿→黄→红) + 职业字（roster 行无职业 → 「英」回退）
func _draw_disc(box: Rect2, is_ally: bool, ratio: float) -> void:
	var c := box.position + box.size * 0.5
	var r := minf(box.size.x, box.size.y) * 0.5 - 2.0
	if r <= 4.0:
		return
	draw_circle(c, r, Color(0.02, 0.04, 0.07, 0.92))
	draw_arc(c, r, 0, TAU, 32, C_ALLY if is_ally else C_ENEMY, 3.0, true)
	if ratio > 0.0:
		var hc := Color(0.35, 1.0, 0.5) if ratio > 0.5 else (Color(1.0, 0.85, 0.25) if ratio > 0.25 else Color(1.0, 0.3, 0.3))
		draw_arc(c, r - 5.0, -PI / 2.0, -PI / 2.0 + TAU * ratio, 24, hc, 3.0, true)
	var gs := float(int(r * 0.8))
	if gs < 6.0:
		return
	draw_string(_f, Vector2(c.x - r, c.y + gs * 0.2), "英",
			HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, int(gs), Color(0.9, 0.9, 0.9).lightened(0.25))

