func _draw_mid(x0: float, x1: float, cy: float, e: Array, is_own: bool, fs_: float) -> void:
	var chips := [
		["heart", Color(0.45, 1.0, 0.55), "%d/%d" % [int(e[4]), int(e[5])]],
		["sword", Color(1.0, 0.62, 0.24), "%d" % int(e[11])],
		["spark", Color(0.72, 0.5, 1.0), "%d" % int(e[12])],
		["shield", Color(1.0, 0.78, 0.3), "%d" % int(e[13])],
		["gem", Color(0.4, 0.88, 1.0), "%d" % int(e[14])],
		["chev", Color(0.45, 0.9, 0.7), "%.0f" % float(e[15])],
	]
	var skills := _skill_texts(is_own)
	var icon := 20.0
	var r1 := maxf(icon, _th(fs_))
	var has_sk := skills.size() > 0
	var r2 := _th(fs_) if has_sk else 0.0
	var total := r1 + (1.0 + r2 if has_sk else 0.0)
	var y1 := cy - total * 0.5
	var cx := x0
	for c in chips:
		var t := str(c[2])
		if cx + icon + 4.0 + _tw(t, fs_) > x1:
			break
		var tint: Color = c[1]
		_draw_stat_icon(Vector2(cx + icon * 0.5, y1 + r1 * 0.5), icon * 0.5, str(c[0]), tint)
		_text(Vector2(cx + icon + 4.0, y1 + (r1 - _th(fs_)) * 0.5 + _asc(fs_)), t, fs_, tint.lightened(0.35))
		cx += icon + 4.0 + _tw(t, fs_) + 14.0
	if not has_sk:
		return
	var y2 := y1 + r1 + 1.0
	var sx := x0
	for c in skills:
		var t := str(c[0])
		if sx + _tw(t, fs_) > x1:
			break
		var col: Color = c[1]
		_text(Vector2(sx, y2 + _asc(fs_)), t, fs_, col)
		sx += _tw(t, fs_) + 8.0

# host row_skills：技能「名 Lv.x (CD/就绪)」+ 召唤师技能。roster 行不带技能数据，
# 仅本机英雄能用 own 快照（levels/cd/summoner_name/summoner_cd）近似，其余留空。
func _skill_texts(is_own: bool) -> Array:
	var out: Array = []
	if not is_own:
		return out
	var lv: Array = own.get("levels", [])
	var cd: Array = own.get("cd", [])
	for i in range(mini(3, lv.size())):
		if int(lv[i]) <= 0:
			continue
		var rem := float(cd[i]) if i < cd.size() else 0.0
		var cd_t := "(%.1fs)" % rem if rem > 0.0 else "(就绪)"
		out.append(["技能%d Lv.%d %s" % [i + 1, int(lv[i]), cd_t],
				Color.GRAY if rem > 0.0 else Color.LIGHT_CYAN])
	var sn := str(own.get("summoner_name", ""))
	if sn != "":
		var scd := float(own.get("summoner_cd", 0.0))
		out.append(["%s %s" % [sn, ("(%.1fs)" % scd if scd > 0.0 else "(就绪)")],
				Color.GRAY if scd > 0.0 else Color.GOLD])
	return out

