# host StatIcon：彩色圆徽章 + 矢量图形（爱心/剑/四芒星/盾/宝石/双箭头）
func _draw_stat_icon(c: Vector2, r: float, shape: String, tint: Color) -> void:
	draw_circle(c, r, tint.darkened(0.62))
	draw_arc(c, r, 0, TAU, 24, tint, 2.0, true)
	var k := r * 0.72
	var col := tint.lightened(0.35)
	match shape:
		"heart":
			draw_circle(c + Vector2(-0.42, -0.12) * k, k * 0.5, col)
			draw_circle(c + Vector2(0.42, -0.12) * k, k * 0.5, col)
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(-0.92, 0.0) * k, c + Vector2(0.92, 0.0) * k, c + Vector2(0.0, 0.98) * k]), col)
		"sword":
			var e0 := c + Vector2(-0.5, 0.7) * k
			var e1 := c + Vector2(0.85, -0.55) * k
			var d := (e1 - e0).normalized()
			var n := Vector2(-d.y, d.x)
			draw_line(e0 - n * k * 0.28, e0 + n * k * 0.28, col, 1.8)
			draw_line(e0, e1, col, 3.0)
			draw_circle(e0 - d * k * 0.18, k * 0.1, col)
		"spark":
			var pts := PackedVector2Array()
			for i in range(8):
				var ang := float(i) * PI / 4.0 + PI / 8.0
				var rad := k * 0.85 if i % 2 == 0 else k * 0.2
				pts.append(c + Vector2(cos(ang), sin(ang)) * rad)
			draw_colored_polygon(pts, col)
		"shield":
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(-0.82, -0.7) * k, c + Vector2(0.82, -0.7) * k,
				c + Vector2(0.82, 0.1) * k, c + Vector2(0.0, 0.96) * k,
				c + Vector2(-0.82, 0.1) * k]), col)
		"gem":
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(0.0, -0.92) * k, c + Vector2(0.66, -0.22) * k,
				c + Vector2(0.0, 0.92) * k, c + Vector2(-0.66, -0.22) * k]), col)
		"chev":
			for sx in PackedFloat32Array([0.0, 0.45]):
				var xo: float = c.x + sx * k
				draw_line(Vector2(xo - k * 0.3, c.y - k * 0.5), Vector2(xo + k * 0.05, c.y), col, 2.0)
				draw_line(Vector2(xo - k * 0.3, c.y + k * 0.5), Vector2(xo + k * 0.05, c.y), col, 2.0)

