	if is_own:
		draw_style_box(_sb_own, card)
	var cy := card.position.y + card.size.y * 0.5
	var x := card.position.x + 10.0   # border_left 4 + content_margin 6
	# 1) 头像盘（host HeroDisc 60 宽：阵营外环 + 血量状态弧 + 职业字）
	var maxhp := maxf(1.0, float(e[5]))
	var ratio := clampf(float(e[4]) / maxhp, 0.0, 1.0)
	_draw_disc(Rect2(Vector2(x, card.position.y + 2.0), Vector2(DISC_W, card.size.y - 4.0)),
			is_ally, ratio, _role_of(e), dead)
	x += DISC_W + 8.0
	# 2) 状态 / 名字 / 等级（host left_box 180 宽：font_main、font_main、font_sub，1px 行距）
	var nm := str(e[1])
	if _is_ai(e):
		nm += "[AI]"
	var name_col := Color.WHITE if is_ally else Color(1.0, 0.55, 0.55)
	if is_own:
		nm = ">> " + nm
		name_col = Color(1.0, 0.88, 0.4)
	# 状态行：host 阵亡→复活读秒(红) / hp<30%→残血(橙) / 其余 存活(绿)
	var st_txt := "存活"
	var st_col := Color.GREEN
	if dead:
		st_txt = _dead_text(e)
		st_col = Color.RED
	elif ratio < 0.3:
		st_txt = "残血"
		st_col = Color.ORANGE
	_vstack(x, cy, [st_txt, nm, "Lv.%d" % int(e[3])], [fm, fm, fs_],
			[_dim(st_col, dead), _dim(name_col, dead), _dim(Color.GOLD, dead)], 1.0)
	# 3) 中间（属性圆徽章 + 技能行）、4) 右侧（KDA/总经济/装备）；右列按装备文本宽撑开（host 每件 min 80）
	var right_w := maxf(RIGHT_W, _equip_w(e, fs_))
	var mid_x := x + LEFT_W + 8.0
	var mid_r := card.end.x - 7.0 - right_w - 8.0
	_draw_mid(mid_x, mid_r, cy, e, is_own, fs_, dead)
	var rx := card.end.x - 7.0 - right_w
	_draw_right(Rect2(Vector2(rx, card.position.y + 2.0), Vector2(right_w, card.size.y - 4.0)),
			e, cy, fs_, dead)

