func _equip_w(e: Array, fs_: float) -> float:
	var eqs := _equip_list(e)
	var eq_sz := maxf(10.0, fs_ - 1.0)
	var w := 0.0
	var n := mini(eqs.size(), 6)
	if n <= 0:
		return 0.0
	for i in range(n):
		var t := str(eqs[i][0])
		w += maxf(80.0, _tw(t, eq_sz)) + 3.0
	return w

# host HeroDisc：暗内盘 + 阵营色外环 + 血量弧(绿→黄→红) + 职业字；阵亡灰环、无血量弧
func _draw_disc(box: Rect2, is_ally: bool, ratio: float, role: String, dead: bool) -> void:
	var c := box.position + box.size * 0.5
	var r := minf(box.size.x, box.size.y) * 0.5 - 2.0
	if r <= 4.0:
		return
	var st := _role_style(role)
	var team_col := C_ALLY if is_ally else C_ENEMY
	if dead:
		team_col = Color(0.32, 0.32, 0.36)
	draw_circle(c, r, Color(0.02, 0.04, 0.07, 0.92))
	draw_arc(c, r, 0, TAU, 32, team_col, 3.0, true)
	if not dead and ratio > 0.0:
		var hc := Color(0.35, 1.0, 0.5) if ratio > 0.5 else (Color(1.0, 0.85, 0.25) if ratio > 0.25 else Color(1.0, 0.3, 0.3))
		draw_arc(c, r - 5.0, -PI / 2.0, -PI / 2.0 + TAU * ratio, 24, hc, 3.0, true)
	var gs := float(int(r * 0.8))
	if gs < 6.0:
